const base = JsonUtils.readJsonFromFile1('Appcreation');
const p = await JsonUtils.modifyPayload({
    pan_card: sharedNegPan, mobile: sharedNegMobile, last_name: 'Reddy',
    'employment.emp_type':           'SALARIED',
    'employment.income':             50000,
    'employment.annual_turnover':    'Rs.0 to 40 lakhs',
    'employment.nature_of_business': 'Manufacturer',
    'employment.business_type':      'PROPRIETORSHIP',
}, base);
const r = await apiRequestWithRetry(constants.baseURI2, 'post', constants.pathInit, p, fkHeaders);
addContext(this, { title: 'App Create Response', value: r.body });
expect(r.status, 'SALARIED + business fields should return 400').to.equal(400);
expect(r.body.message).to.include('SELFEMP');

