const { appId, res, txnId } = await createSenpAppAndOffer(this, {
    'employment.emp_type':        'SELFEMP',
    'employment.annual_turnover': 'Rs.40 lakhs to 1.5 Cr.',
}, { removeIncome: true });
expect(res.status, 'SENP without salary must still create the app (gate satisfied by turnover)').to.equal(200);
expect(appId, 'application_id must be created').to.be.a('string').and.not.be.empty;
// "Able to move" — OMNI_1 generated means underwriting ran (app progressed past offer).
const omni = await fetchOmniStages(this, appId, ['OMNI_1', 'OMNI_PRE', 'OMNI_POST']);
expect(omni.OMNI_1.input, 'OMNI_1 must exist — proves the no-salary SENP app moved forward').to.exist;
// And it can advance into banking without a salary value.
const bank = await advanceToBanking(this, appId);
expect(bank.bankTxnId, 'banking init must succeed for a no-salary SENP app (able to move)').to.be.ok;
await addOmniSummaryPanel(this, appId, {
    annual_turnover: 'Rs.40 lakhs to 1.5 Cr.',
}, { rejected: bank.bankingStatus === 'Rejected' });
